"""Chapter 1 Measurement: written-answer questions, 5 per level (quantities and units, prefixes, instruments, scalars and vectors)."""
from .. import figs, figs2, sketches
from ..marker import Pitfall, Point
from .base import written

P = Point
PF = Pitfall

# ---------------------------------------------------------------- L1
written("w1_physical_quantity", 1, 1, "1a",
        stem="State the two parts that make up a physical quantity, using the example '2.5 kg'.",
        points=[P("a numerical magnitude (2.5) and a unit (kg)", ["number and a unit", "magnitude and a unit", "numerical value and a unit", "numerical magnitude", "number and unit", "value and its unit", "2.5 is the", "kg is the unit"])],
        model_answer="A physical quantity consists of a numerical magnitude and a unit: in 2.5 kg, 2.5 is the magnitude and kg is the unit.",
        hints=["Look at '2.5 kg'. What are its two parts?",
               "One part is a number; the other says what the number counts.",
               "Name both parts, using the example."],
        keywords="numerical magnitude and unit",
        sample_pass=["A number (2.5) and a unit (kg)", "the numerical magnitude and the unit"],
        sample_fail=["Mass and weight", "A decimal and a letter"])

written("w1_base_quantities", 1, 1, "1b",
        stem="Name three SI base quantities and give the SI unit of each.",
        points=[P("any three of: mass (kg), length (m), time (s), current (A), temperature (K), amount of substance (mol)",
                  ["mass kg", "mass kilogram", "length m", "length metre", "length meter", "time s", "time second", "current a", "current ampere", "temperature k", "temperature kelvin", "amount of substance mol", "mole"])],
        pitfalls=[PF(["force", "speed", "volume", "energy", "density"], "Those are DERIVED quantities, built from the base quantities. The base quantities are mass, length, time, current, temperature and amount of substance.")],
        model_answer="For example: mass (kilogram, kg), length (metre, m) and time (second, s). The others are electric current (ampere, A), temperature (kelvin, K) and amount of substance (mole, mol).",
        hints=["Base quantities are the ones that everything else is built from; there are six.",
               "Think of what a balance, a ruler and a stopwatch measure.",
               "Name three quantities and their units."],
        keywords="mass kg, length m, time s, current A, temperature K, amount of substance mol",
        sample_pass=["Mass in kilograms, length in metres and time in seconds", "current (A), temperature (K), mass (kg)"],
        sample_fail=["Force, speed and energy", "Weight in newtons and volume in litres"])

written("w1_scalar_vector", 1, 1, "1f",
        stem="State the difference between a scalar quantity and a vector quantity, giving one example of each.",
        points=[P("a scalar has magnitude only; a vector has magnitude and direction", ["magnitude only", "size only", "no direction", "magnitude and direction", "size and direction", "has a direction"]),
                P("examples: scalar such as mass, speed, time, distance, energy; vector such as force, velocity, displacement, acceleration, weight", ["mass", "speed", "time", "distance", "energy", "temperature", "force", "velocity", "displacement", "acceleration", "weight"])],
        model_answer="A scalar quantity has magnitude (size) only, for example mass or speed. A vector quantity has both magnitude and direction, for example force or velocity.",
        hints=["One kind of quantity can point somewhere; the other cannot.",
               "Does it make sense to say '5 kg to the left'? What about '5 N to the left'?",
               "State the difference and give an example of each."],
        keywords="scalar: magnitude only; vector: magnitude and direction",
        sample_pass=["A scalar has size only, like mass; a vector has size and direction, like force", "vectors such as velocity have direction, scalars such as speed do not"],
        sample_fail=["Scalars are bigger than vectors", "A vector is a type of force"])

written("w1_prefix_meaning", 1, 1, "1c",
        stem="State what the prefixes kilo (k) and milli (m) mean, with an example of each.",
        points=[P("kilo = ×1000 (10³), e.g. 1 km = 1000 m", ["1000", "thousand", "10³", "10^3", "km", "kilometre", "kilogram"]),
                P("milli = ÷1000 (10⁻³, one thousandth), e.g. 1 mm = 0.001 m", ["0.001", "thousandth", "10⁻³", "10^-3", "1/1000", "divide by 1000", "mm", "millimetre", "millimeter"])],
        pitfalls=[PF(["milli means 1000", "milli is 1000", "milli = 1000"], "Milli means one THOUSANDTH (0.001); kilo means a thousand.")],
        model_answer="Kilo means one thousand times (10³): 1 km = 1000 m. Milli means one thousandth (10⁻³): 1 mm = 0.001 m.",
        hints=["How many metres in a kilometre? How many millimetres in a metre?",
               "One prefix makes the unit bigger, the other smaller, by the same factor.",
               "Give the meaning of each prefix with an example."],
        keywords="kilo = 1000, milli = 0.001",
        sample_pass=["Kilo means 1000, as in 1 km = 1000 m; milli means a thousandth, as in 1 mm = 0.001 m", "k is 10^3 and m is 10^-3"],
        sample_fail=["Kilo means 100 and milli means 10", "Both mean 1000"])

written("w1_period_meaning", 1, 1, "1e",
        stem="Fig. 1 shows a simple pendulum. State what is meant by the period of the pendulum.",
        points=[P("the time taken for one complete oscillation (swing there and back)", ["one complete oscillation", "one complete swing", "one full swing", "one oscillation", "there and back", "to and fro once", "complete cycle", "time for one"])],
        pitfalls=[PF(["number of oscillations", "oscillations per second", "swings per second"], "Oscillations per second is the FREQUENCY. The period is the time for one oscillation.")],
        model_answer="The period is the time taken for one complete oscillation, i.e. for the bob to swing from one side to the other and back again.",
        hints=["Period is a time. The time for what?",
               "One complete oscillation means returning to the starting point moving the same way.",
               "Write the definition as a sentence."],
        keywords="time for one complete oscillation",
        figure=lambda: sketches.pendulum_sketch(),
        sample_pass=["The time for one complete oscillation", "the time taken to swing there and back once"],
        sample_fail=["The number of swings per second", "The length of the string"])

# ---------------------------------------------------------------- L2
written("w1_choose_instrument", 1, 2, "1e",
        stem="Fig. 1 shows the display of a digital micrometer. State what a digital micrometer is suitable for measuring, and give its precision. Name an instrument you would use instead to measure the length of a pencil.",
        points=[P("small lengths such as the diameter of a wire or thickness of a sheet, to a precision of 0.001 mm", ["wire", "thickness", "small", "thin", "diameter", "0.001 mm", "0.0001 cm", "thousandth of a millimetre"]),
                P("a metre rule (or ruler) for the pencil, precision 0.1 cm (1 mm)", ["ruler", "metre rule", "rule", "0.1 cm", "1 mm"])],
        model_answer="A digital micrometer measures very small lengths, such as the diameter of a wire or the thickness of a sheet of paper, to a precision of 0.001 mm. The length of a pencil (about 15 cm) is best measured with a metre rule or ruler, precision 0.1 cm.",
        hints=["A micrometer only opens about 25 mm. What sorts of objects fit, and how precisely does it read?",
               "A pencil is far too long for a micrometer. Which everyday instrument suits it?",
               "State the micrometer's use and precision, then the instrument for the pencil."],
        keywords="micrometer: small lengths e.g. wire diameter, 0.001 mm; pencil: ruler, 0.1 cm",
        figure=lambda: figs2.digital_display("4.372", "mm", "digital micrometer"),
        sample_pass=["It measures small lengths like the diameter of a wire to 0.001 mm; a pencil would be measured with a ruler", "thickness of thin objects, precision 0.001 mm; use a metre rule for the pencil"],
        sample_fail=["It measures long distances to 1 m", "Use a measuring cylinder for the pencil"])

written("w1_convert_units", 1, 2, "1c",
        stem="A table top is 1.2 m long and 3 cm thick. Explain how to express the length in centimetres and the thickness in metres, and give both values.",
        points=[P("1 m = 100 cm, so 1.2 m = 120 cm", ["120 cm", "120", "multiply by 100", "× 100", "x 100", "100 cm in a metre"]),
                P("3 cm = 3 ÷ 100 m = 0.03 m", ["0.03 m", "0.03", "divide by 100", "÷ 100", "/ 100"])],
        model_answer="There are 100 cm in 1 m, so 1.2 m = 1.2 × 100 = 120 cm. To convert the other way divide by 100: 3 cm = 3 ÷ 100 = 0.03 m.",
        hints=["How many centimetres make one metre?",
               "Going from metres to centimetres the number gets bigger; from centimetres to metres it gets smaller.",
               "Explain the conversion factor and give both answers."],
        keywords="1 m = 100 cm; 120 cm; 0.03 m",
        sample_pass=["Multiply by 100 to get 120 cm, and divide by 100 to get 0.03 m", "1.2 m = 120 cm and 3 cm = 0.03 m"],
        sample_fail=["1.2 m = 12 cm and 3 cm = 0.3 m", "1200 cm and 0.003 m"])

written("w1_digital_calipers_method", 1, 2, "1e",
        stem="Fig. 1 shows a pair of digital calipers being used to measure the diameter of a ball bearing. Describe how to use the calipers to obtain an accurate reading.",
        points=[P("close the jaws first and press zero (or note the zero error) so that the display reads 0.00 mm with nothing between the jaws", ["zero", "close the jaws", "jaws closed", "0.00", "reset", "zero error"]),
                P("close the jaws gently on the object so that they just touch it, without squeezing", ["gently", "just touch", "do not squeeze", "lightly", "firmly", "grip"]),
                P("read the display to 0.01 mm (and repeat at different places to take an average)", ["0.01 mm", "read the display", "repeat", "average", "different places", "mean"])],
        min_points=2,
        model_answer="First close the jaws with nothing between them and press the zero button (or note any zero error) so the display reads 0.00 mm. Then close the jaws gently on the ball bearing until they just touch it, and read the display to 0.01 mm. Repeat at different positions and take the average.",
        hints=["What should the display show when the jaws are closed on nothing?",
               "How tightly should the jaws hold the object, and to how many decimal places does the display read?",
               "Describe the zero step, the measuring step and how to improve reliability."],
        keywords="zero the display with jaws closed; close jaws gently on the object; read to 0.01 mm; repeat and average",
        figure=lambda: figs2.digital_calipers("12.47", object_label="ball bearing"),
        sample_pass=["Close the jaws and zero the display, then close them gently on the ball bearing and read to 0.01 mm, repeating for an average",
                     "check for zero error with the jaws closed, grip the object lightly and read the display; repeat at several places"],
        sample_fail=["Read the number nearest the end of the jaws", "Squeeze the jaws as hard as possible and read once"])

written("w1_pendulum_period_method", 1, 2, "1e",
        stem="Fig. 1 shows a pendulum. Describe how you would measure its period accurately with a stopwatch.",
        points=[P("time a large number of complete oscillations (e.g. 20) rather than one", ["20 oscillations", "many oscillations", "number of oscillations", "several oscillations", "10 oscillations", "complete oscillations"]),
                P("divide the total time by the number of oscillations to get the period", ["divide by the number", "divided by 20", "total time ÷", "total time divided", "average", "÷ the number"]),
                P("start and stop timing as the bob passes the centre (rest position), and repeat the measurement", ["centre", "rest position", "lowest point", "equilibrium", "repeat", "fiducial", "marker"])],
        min_points=2,
        model_answer="Start the stopwatch as the bob passes its rest position and count 20 complete oscillations, stopping the watch as it passes the same point moving the same way. Divide the total time by 20 to find the period. Timing many oscillations reduces the effect of reaction time; repeating and averaging improves the result further.",
        hints=["One swing is too quick to time accurately. What could you time instead?",
               "Where in the swing is the bob moving fastest, making it easiest to judge when it passes?",
               "Describe what you time, how you calculate the period, and how you reduce errors."],
        keywords="time 20 oscillations, divide by 20, start/stop at centre, repeat",
        figure=lambda: sketches.pendulum_sketch(),
        sample_pass=["Time 20 complete oscillations starting from the centre position and divide by 20; repeat and average", "count many swings and divide the total time by the number of oscillations"],
        sample_fail=["Time one swing with the stopwatch", "Measure the length of the string"])

written("w1_measuring_cylinder_reading", 1, 2, "1e",
        stem="Fig. 1 shows water in a measuring cylinder. Describe how to read the volume correctly and state the precision of this cylinder.",
        points=[P("read at eye level with the bottom of the meniscus on the scale", ["eye level", "bottom of the meniscus", "meniscus", "level with the surface", "avoid parallax"]),
                P("each small division is 2 cm³ (so the precision is 2 cm³, and the reading here is 56 cm³)", ["2 cm", "2 ml", "small division", "smallest division", "56"])],
        model_answer="Place the cylinder on a flat surface and read with the eye level with the liquid surface, taking the reading at the bottom of the curved meniscus to avoid parallax error. The small divisions are 2 cm³ apart, so the cylinder reads to 2 cm³; here the volume is 56 cm³.",
        hints=["The surface of the water is curved. Which part of the curve do you read, and from where?",
               "Look at the scale: what is the gap between the numbered marks, and how many small divisions fill it?",
               "Describe the reading technique and give the precision."],
        keywords="eye level, bottom of meniscus, division = 2 cm³",
        figure=lambda: figs.measuring_cylinder(56),
        sample_pass=["Read the bottom of the meniscus at eye level; each small division is 2 cm³", "at eye level to avoid parallax, bottom of the meniscus, precision 2 ml"],
        sample_fail=["Read the top of the water from above", "Each division is 10 cm³"])

# ---------------------------------------------------------------- L3
written("w1_why_micrometer_for_wire", 1, 3, "1e",
        stem="A student wants to measure the diameter of a thin copper wire, about 0.5 mm. Explain why a metre rule is unsuitable and why a digital micrometer is used instead. Fig. 1 shows the micrometer display.",
        points=[P("a metre rule reads only to 0.1 cm (1 mm), which is larger than the wire's diameter, so the reading would be very imprecise", ["0.1 cm", "1 mm", "too large", "not precise", "imprecise", "larger than the wire", "cannot measure", "too coarse"]),
                P("a micrometer reads to 0.001 mm, giving a precise reading of a small length", ["0.001 mm", "0.01 mm", "0.0001 cm", "precise", "precision", "small lengths", "accurate"]),
                P("its jaws close firmly on the wire, so the diameter is measured directly rather than estimated", ["jaws", "close on the wire", "grips", "directly", "ratchet", "hold the wire"])],
        min_points=2,
        model_answer="A metre rule has a precision of 0.1 cm (1 mm), which is larger than the wire's diameter, so any reading would be hopelessly imprecise, and it is hard to line a round wire against a scale. A digital micrometer reads to 0.001 mm and its jaws close firmly on the wire, so the diameter is measured directly and precisely.",
        hints=["Compare the smallest division of a metre rule with the size of the wire.",
               "What precision does a micrometer have, and how does it hold the wire?",
               "Explain the rule's unsuitability and the micrometer's advantages."],
        keywords="rule precision 1 mm too coarse; micrometer 0.001 mm, jaws grip wire",
        figure=lambda: figs2.digital_display("0.524", "mm", "digital micrometer"),
        sample_pass=["A ruler only reads to 1 mm which is bigger than the wire, but a micrometer reads to 0.001 mm and its jaws grip the wire", "the rule is too coarse; the micrometer is precise to 0.001 mm"],
        sample_fail=["A ruler is too short", "The micrometer is made of metal like the wire"])

written("w1_zero_error", 1, 3, "1e",
        stem="Before measuring, a student closes the jaws of a pair of digital calipers and finds the reading shown in Fig. 1 is not zero. Explain what this shows and how the student should deal with it.",
        points=[P("the instrument has a zero error: it gives a non-zero reading when it should read zero", ["zero error", "does not read zero", "not zero when closed", "offset", "systematic error"]),
                P("record the zero error, then subtract it from (or correct) every measurement taken", ["subtract", "correct", "take away", "adjust", "allow for", "add or subtract", "every reading"]),
                P("if the reading is positive the error is subtracted; if negative (below zero) its size is added", ["positive", "negative", "added", "subtracted", "below zero", "sign"])],
        min_points=2,
        model_answer="The calipers have a zero error: they give a non-zero reading when the jaws are closed and the true value is zero. The student should note the zero error and correct every measurement by subtracting it: a positive zero error is subtracted from each reading, and if the error is negative its size is added.",
        hints=["What should an instrument read when there is nothing between its jaws?",
               "The same error will appear in every reading. How do you remove it?",
               "Name the error and explain the correction."],
        keywords="zero error, subtract from each reading (sign matters)",
        figure=lambda: figs2.caliper_pair("0.03", "9.38", "jaws closed", "object between the jaws"),
        sample_pass=["It has a zero error, so the student must subtract that error from every reading", "a zero error; correct each measurement by taking the error away, adding if it is negative"],
        sample_fail=["The calipers are broken and cannot be used", "Ignore it because it is small"])

written("w1_displacement_vs_distance", 1, 3, "1f",
        stem="Fig. 1 shows a student who walks 30 m north and then 40 m east. Explain the difference between the distance she has travelled and her displacement, and give both.",
        points=[P("distance is the total length of the path travelled (a scalar): 30 + 40 = 70 m", ["distance 70", "distance is 70", "distance travelled 70", "travelled 70", "total 70", "path 70", "walked 70", "30 + 40", "distance is a scalar", "distance scalar"], ordered=True, window=4),
                P("displacement is the straight-line distance from start to finish in a stated direction (a vector): 50 m (by Pythagoras)", ["displacement 50", "displacement is 50", "displacement of 50", "finish 50", "finish is 50", "line 50", "pythagoras", "displacement is a vector", "hypotenuse"], ordered=True, window=4)],
        model_answer="Distance is the total length of the path walked, a scalar: 30 + 40 = 70 m. Displacement is the straight-line distance from the starting point to the finishing point together with its direction, a vector: by Pythagoras √(30² + 40²) = 50 m, towards the north-east.",
        hints=["One quantity adds up every step taken; the other only cares about where she ended up relative to the start.",
               "The path is two sides of a right-angled triangle. Which quantity is the hypotenuse?",
               "Define each quantity and give its value."],
        keywords="distance 70 m (scalar, path length); displacement 50 m (vector, straight line)",
        figure=lambda: figs.path_figure(30, 40),
        sample_pass=["Distance is the total path, 70 m; displacement is the straight line from start to finish, 50 m with a direction", "she travelled 70 m but her displacement is 50 m by Pythagoras"],
        sample_fail=["Both are 70 m", "Displacement is 70 m and distance is 50 m"])

written("w1_parallax_error", 1, 3, "1e",
        stem="A student reads a metre rule with her eye to one side of the mark being read. Explain the error this causes and how to avoid it.",
        points=[P("this causes a parallax error: the reading appears shifted because the eye is not directly above the mark", ["parallax", "appears shifted", "wrong position", "misread", "angle", "not directly above"]),
                P("the reading could be too high or too low depending on which side the eye is", ["too high or too low", "too big or too small", "larger or smaller", "either direction", "depends on the side"]),
                P("avoid it by placing the eye directly above / perpendicular to the mark (at right angles to the scale)", ["directly above", "perpendicular", "at right angles", "eye level", "vertically above", "in line with"])],
        min_points=2,
        model_answer="Reading from one side causes a parallax error: the mark appears to line up with the wrong scale division, so the reading is too high or too low depending on which side the eye is on. To avoid it, the eye should be placed directly above the mark, looking at right angles to the scale.",
        hints=["Hold a pencil against a ruler and move your head sideways: what seems to happen to the reading?",
               "Which direction should you look from to avoid this?",
               "Name the error, its effect, and how to avoid it."],
        keywords="parallax error, reading too high or low, eye directly above / perpendicular",
        sample_pass=["It causes parallax error, making the reading too big or too small; the eye should be directly above the mark", "parallax: look perpendicular to the scale to avoid it"],
        sample_fail=["The ruler will bend", "She should use a longer ruler"])

written("w1_order_of_magnitude", 1, 3, "1d",
        stem="Place the following in order of increasing size and give a rough value for each: the diameter of an atom, the thickness of a human hair, the height of a person.",
        points=[P("atom (about 10⁻¹⁰ m), then hair (about 10⁻⁴ m, 0.1 mm), then person (about 2 m)", ["atom", "hair", "person"]),
                P("rough values: atom ~10⁻¹⁰ m; hair ~0.1 mm (10⁻⁴ m); person ~1.5 to 2 m", ["10⁻¹⁰", "10^-10", "0.1 mm", "10⁻⁴", "10^-4", "2 m", "1.7 m", "1.5 m", "1.8 m"])],
        model_answer="In order of increasing size: the diameter of an atom (about 10⁻¹⁰ m), the thickness of a human hair (about 0.1 mm, or 10⁻⁴ m), and the height of a person (about 1.7 m).",
        hints=["Which is smallest? Atoms are far smaller than anything you can see.",
               "A hair is about a tenth of a millimetre. A person is about two metres.",
               "Give the order and a rough value for each."],
        keywords="atom 10⁻¹⁰ m < hair 10⁻⁴ m < person ~2 m",
        sample_pass=["Atom (10^-10 m), hair (0.1 mm), person (about 1.7 m)", "smallest is the atom at about 10⁻¹⁰ m, then a hair at 10⁻⁴ m, then a person at 2 m"],
        sample_fail=["Hair, atom, person", "Person, hair, atom"])

# ---------------------------------------------------------------- L4
written("w1_digital_micrometer_method", 1, 4, "1e",
        stem="Fig. 1 shows the display of a digital micrometer with its jaws closed on nothing. Describe how a student should use the micrometer to find an accurate value for the diameter of a wire.",
        points=[P("with the jaws closed on nothing the display shows a zero error, which must be subtracted from (or, if negative, added to) each reading, or removed with the zero button", ["zero error", "subtract", "take away", "zero button", "reset", "press zero", "correct", "add if negative"]),
                P("close the jaws on the wire using the ratchet so that it just grips without squashing the wire, and read the display to 0.001 mm", ["ratchet", "gently", "just grips", "do not squash", "not squeeze", "0.001 mm", "read the display"]),
                P("repeat at several places along the wire (and at different orientations) and take the average", ["repeat", "several places", "different places", "average", "mean", "along the wire"])],
        min_points=2,
        model_answer="The display shows a zero error, so the student should press the zero button (or note the error and subtract it from every reading, adding it if the error is negative). Close the jaws on the wire using the ratchet so they just grip it without squashing it, and read the display to 0.001 mm. Repeat at several places along the wire and take the average.",
        hints=["What does a non-zero display with closed jaws tell you, and what should be done about it?",
               "How tightly should the jaws close on a soft copper wire, and to how many decimal places is the display read?",
               "Describe the zero-error step, the measuring step and how to make the result reliable."],
        keywords="zero error removed or subtracted; ratchet, jaws just grip; read to 0.001 mm; repeat and average",
        figure=lambda: figs2.digital_display("-0.002", "mm", "jaws closed"),
        sample_pass=["Press zero first or subtract the zero error, close the jaws with the ratchet so the wire is not squashed, read to 0.001 mm and repeat along the wire for an average",
                     "note the zero error and correct each reading; grip the wire gently; take readings at several places and average"],
        sample_fail=["Read the number on the thimble", "Measure the wire with a ruler as a check"])

