written("w1_precision_vs_accuracy", 1, 4, "1e",
        stem="A student measures the length of a rod three times with a ruler and gets 24.6 cm, 24.6 cm and 24.7 cm; the rod's true length is 25.0 cm. Comment on the precision and the accuracy of the measurements and suggest a cause.",
        points=[P("the readings are precise (close to each other, repeatable)", ["precise", "precision", "close to each other", "repeatable", "consistent", "agree with each other"]),
                P("but not accurate, because they are all about 0.4 cm below the true value", ["not accurate", "inaccurate", "below the true value", "all too low", "systematic", "away from the true"]),
                P("a likely cause is a systematic error such as a zero error (worn ruler end) or a consistent parallax error", ["zero error", "worn end", "damaged end", "systematic error", "parallax", "not starting at zero"])],
        min_points=2,
        model_answer="The three readings are close together, so the measurements are precise (repeatable). However, they are all about 0.4 cm below the true value of 25.0 cm, so they are not accurate. A consistent offset like this suggests a systematic error, for example a zero error from a worn end of the ruler or reading from the wrong starting mark.",
        hints=["Precision is about agreement between repeats; accuracy is about closeness to the true value. Judge each.",
               "If every reading is wrong by about the same amount in the same direction, what kind of error is that?",
               "Comment on precision, on accuracy, and suggest a cause."],
        keywords="precise (repeatable) but not accurate (all 0.4 cm low); systematic / zero error",
        sample_pass=["The readings are precise because they agree closely but not accurate as they are all below 25.0 cm, probably a zero error from a worn ruler end",
                     "precise but inaccurate; a systematic error like parallax or a damaged ruler end"],
        sample_fail=["The readings are accurate but not precise", "The student cannot read a ruler"])

